    const {isNew, most_recentlyUpdated_bpName, most_recentlyUpdated_bpSysId, outstandingSteps} = api.state;
    if (isNew) {
      return "First-time users can follow the “Build a foundation” maturity track to discover which Best Practices to start with.";
    } else {
      let numberToWordsMap = {
        "0" : "Zero",
        "1" : "One",
        "2" : "Two",
        "3" : "Three",
        "4" : "Four",
        "5" : "Five",
        "6" : "Six",
        "7" : "Seven",
        "8" : "Eight",
        "9" : "Nine",
        "10" : "Ten" 
      }; 
      const progressInfoText = "Most recent progress was made in the \"" + most_recentlyUpdated_bpName + "\". " + numberToWordsMap[outstandingSteps] + " step(s) remain until completion.";
      return progressInfoText;
    }
  }
}

