/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    var prevQuery = event.payload.prevQuery;
	var filterQuery = event.payload.query;
    if (prevQuery) {
        filterQuery = filterQuery.replace(prevQuery, '');
    }
	var resVal = '';
    if (filterQuery.includes('goals')) {
		resVal = 'Goals';
	}
	else if (filterQuery.includes('priority')) {
		resVal = 'Priority';
	}
	else if (filterQuery.includes('name')) {
		resVal = 'Name';
	}
	else if (filterQuery.includes('status')) {
		resVal = 'Status';
	}
	else if (filterQuery.includes('security_privacy_capabilities')) {
		resVal = 'Security and privacy capabilities';
	}
	else if (filterQuery.includes('maturity_level')) {
		resVal = 'Maturity level';
	}
    return {
        event: 'Update best practice list filter',
        value: {
            'Filter update': resVal
        }
    };
}

